1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	};
10	const COMPONENT_BLOCK_SIZE = 3;
11	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
12	
13	type Item = {
14	  type: string;
15	  material?: string;
16	  enchantmentLevel?: number;
17	  cursed?: boolean;
18	};
19	
20	type Step = {
21	  op: string;
22	  items: Item[];
23	};
24	
25	type Scenario = {
26	  customer: { yearsWithMHPCO: number };
27	  steps: Step[];
28	};
29	
30	type QuoteResult = {
31	  premium: number;
32	};
33	
34	type ScenarioOutput = {
35	  results: QuoteResult[];
36	};
37	
38	const isComponentBlock = (items: Item[]): boolean =>
39	  items.length === COMPONENT_BLOCK_SIZE &&
40	  items.every((item) => item.type === items[0].type);
41	
42	const basePremiumForItems = (items: Item[]): number => {
43	  if (isComponentBlock(items)) return COMPONENT_BLOCK_BASE_PREMIUM;
44	  return items.reduce(
45	    (total, item) => total + BASE_PREMIUM_BY_ITEM_TYPE[item.type],
46	    0,
47	  );
48	};
49	
50	const premiumBeforeProcessingFee = (items: Item[]): number => {
51	  const basePremium = basePremiumForItems(items);
52	  return basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
53	};
54	
55	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
56	  results: scenario.steps.map((step) => ({
57	    premium: Math.ceil(premiumBeforeProcessingFee(step.items) + PROCESSING_FEE),
58	  })),
59	});
